result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/hash-router/src/router.js", "content": "/**
 * Minimal hash-based SPA router that works entirely in jsdom.
 *
 * - Routes are patterns like "#/users/:id" mapped to handler functions.
 * - Listens to the window "hashchange" event (no History API).
 * - Supports a notFound fallback and programmatic navigate(path).
 * - Intercepts clicks on anchors whose href starts with "#/" so plain
 *   left-clicks navigate through the router; ctrl/meta/shift/alt clicks
 *   keep their default browser behavior.
 */

function parseHash(hash) {
  // Strip leading "#" then split path from query string.
  let raw = hash.replace(/^#/, '');
  if (!raw.startsWith('/')) raw = '/' + raw;
  const qIndex = raw.indexOf('?');
  const path = qIndex === -1 ? raw : raw.slice(0, qIndex);
  const queryString = qIndex === -1 ? '' : raw.slice(qIndex + 1);
  return { path, queryString };
}

function parseQuery(queryString) {
  const query = {};
  if (!queryString) return query;
  for (const pair of queryString.split('&')) {
    if (!pair) continue;
    const eq = pair.indexOf('=');
    const key = eq === -1 ? pair : pair.slice(0, eq);
    const value = eq === -1 ? '' : pair.slice(eq + 1);
    try {
      query[decodeURIComponent(key)] = decodeURIComponent(value);
    } catch {
      query[key] = value;
    }
  }
  return query;
}

function matchRoute(pattern, path) {
  const patternParts = pattern.split('/').filter(Boolean);
  const pathParts = path.split('/').filter(Boolean);
  if (patternParts.length !== pathParts.length) return null;

  const params = {};
  for (let i = 0; i < patternParts.length; i++) {
    const p = patternParts[i];
    if (p.startsWith(':')) {
      params[p.slice(1)] = decodeURIComponent(pathParts[i]);
    } else if (p !== pathParts[i]) {
      return null;
    }
  }
  return params;
}

export function createRouter(routes, { onChange } = {}) {
  const compiled = Object.entries(routes).map(([pattern, handler]) => ({
    pattern: pattern.replace(/^#/, ''),
    handler,
  }));

  let currentHandler = null;
  let listening = false;

  function resolve() {
    const { path, queryString } = parseHash(window.location.hash);
    const query = parseQuery(queryString);

    let matched = null;
    let handler = null;
    for (const route of compiled) {
      const params = matchRoute(route.pattern, path);
      if (params) {
        handler = route.handler;
        matched = { params, query };
        break;
      }
    }

    if (!handler && routes.notFound) {
      handler = routes.notFound;
      matched = { params: {}, query };
    }

    currentHandler = handler || null;
    if (currentHandler) currentHandler(matched);
    if (typeof onChange === 'function') {
      onChange({ path, query, matched: Boolean(handler), handled: Boolean(currentHandler) });
    }
    return matched;
  }

  function start() {
    if (!listening) {
      window.addEventListener('hashchange', resolve);
      listening = true;
    }
    resolve();
  }

  function stop() {
    if (listening) {
      window.removeEventListener('hashchange', resolve);
      listening = false;
    }
    currentHandler = null;
  }

  /**
   * Navigate programmatically by setting location.hash.
   * The resulting hashchange event triggers resolution; if the hash is
   * unchanged (setting it is a no-op), resolve directly.
   */
  function navigate(path) {
    const target = path.startsWith('#') ? path : '#' + path;
    if (window.location.hash === target) {
      resolve();
    } else {
      window.location.hash = target;
    }
  }

  /** Anchor click interceptor. Returns true if it handled the click. */
  function handleClick(event) {
    if (event.defaultPrevented) return false;
    if (event.button !== 0) return false;
    // Preserve default behavior for modified clicks (new tab/window/etc).
    if (event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return false;

    const anchor =
      event.target && typeof event.target.closest === 'function'
        ? event.target.closest('a[href]')
        : null;
    if (!anchor) return false;

    const href = anchor.getAttribute('href');
    if (!href || !href.startsWith('#/')) return false;

    event.preventDefault();
    navigate(href);
    return true;
  }

  function installLinkInterceptor(root = document) {
    root.addEventListener('click', handleClick);
    return () => root.removeEventListener('click', handleClick);
  }

  start();

  return {
    resolve,
    start,
    stop,
    navigate,
    handleClick,
    installLinkInterceptor,
    get currentHandler() {
      return currentHandler;
    },
  };
}
