result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/hash-router/test/router.test.js", "content": "import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { createRouter } from '../src/router.js';

function setHashAndDispatch(hash) {
  window.location.hash = hash;
  window.dispatchEvent(new HashChangeEvent('hashchange'));
}

function click(anchor, { ctrlKey = false, metaKey = false } = {}) {
  const event = new MouseEvent('click', {
    bubbles: true,
    cancelable: true,
    button: 0,
    ctrlKey,
    metaKey,
  });
  anchor.dispatchEvent(event);
  return event.defaultPrevented;
}

describe('createRouter', () => {
  let cleanupFns;

  beforeEach(() => {
    cleanupFns = [];
    window.location.hash = '';
  });

  afterEach(() => {
    for (const fn of cleanupFns) fn();
  });

  it('invokes the matching handler with params on hashchange', () => {
    const users = vi.fn();
    createRouter({ '#/users/:id': users });
    cleanupFns.push(() => window.dispatchEvent(new HashChangeEvent('hashchange')));

    setHashAndDispatch('#/users/42');

    expect(users).toHaveBeenCalledTimes(1);
    expect(users).toHaveBeenCalledWith(expect.objectContaining({ params: { id: '42' } }));
  });

  it('matches static routes exactly', () => {
    const home = vi.fn();
    const users = vi.fn();
    createRouter({ '#/': home, '#/users/:id': users });

    setHashAndDispatch('#/');
    expect(home).toHaveBeenCalledTimes(1);
    expect(users).not.toHaveBeenCalled();
  });

  it('parses query params from after the ? in the hash', () => {
    const search = vi.fn();
    createRouter({ '#/search': search });

    setHashAndDispatch('#/search?q=hello%20world&page=2&flag');

    expect(search).toHaveBeenCalledWith({
      params: {},
      query: { q: 'hello world', page: '2', flag: '' },
    });
  });

  it('passes query alongside route params', () => {
    const handler = vi.fn();
    createRouter({ '#/users/:id/posts': handler });

    setHashAndDispatch('#/users/7/posts?sort=asc');

    expect(handler).toHaveBeenCalledWith({ params: { id: '7' }, query: { sort: 'asc' } });
  });

  it('falls back to notFound for unmatched routes', () => {
    const home = vi.fn();
    const notFound = vi.fn();
    createRouter({ '#/': home, notFound });

    setHashAndDispatch('#/nope/deeper');
    expect(notFound).toHaveBeenCalledTimes(1);
    expect(notFound).toHaveBeenCalledWith(expect.objectContaining({ params: {} }));
    expect(home).not.toHaveBeenCalled();

    // Matching routes bypass notFound.
    setHashAndDispatch('#/');
    expect(home).toHaveBeenCalledTimes(1);
    expect(notFound).toHaveBeenCalledTimes(1);
  });

  it('navigate(path) round-trips through hashchange', () => {
    const user = vi.fn();
    const router = createRouter({ '#/users/:id': user });
    cleanupFns.push(() => router.stop());

    router.navigate('/users/99?tab=bio');

    expect(window.location.hash).toBe('#/users/99?tab=bio');
    expect(user).toHaveBeenCalledWith({ params: { id: '99' }, query: { tab: 'bio' } });
  });

  it('navigate to the same path still re-resolves', () => {
    const home = vi.fn();
    const router = createRouter({ '#/': home });
    cleanupFns.push(() => router.stop());

    window.location.hash = '#/';
    router.navigate('/');
    expect(home).toHaveBeenCalledTimes(1);
    router.navigate('#/');
    expect(home).toHaveBeenCalledTimes(2);
  });

  it('calls onChange for every resolution', () => {
    const onChange = vi.fn();
    const router = createRouter({ '#/a': () => {} }, { onChange });
    cleanupFns.push(() => router.stop());

    setHashAndDispatch('#/a');
    setHashAndDispatch('#/missing');

    expect(onChange).toHaveBeenCalledTimes(3); // initial + two changes
    expect(onChange.mock.calls[2][0]).toMatchObject({ path: '/missing', handled: false });
  });

  describe('link-click interceptor', () => {
    function setup() {
      document.body.innerHTML = '<a href="#/users/5" id="link">user</a>';
      const handler = vi.fn();
      const anchor = document.getElementById('link');
      const router = createRouter({ '#/users/:id': handler });
      const uninstall = router.installLinkInterceptor(document);
      cleanupFns.push(uninstall);
      cleanupFns.push(() => {
        document.body.innerHTML = '';
      });
      return { handler, anchor };
    }

    it('navigates on a plain left click and prevents default', () => {
      const { handler, anchor } = setup();

      const prevented = click(anchor);

      expect(prevented).toBe(true);
      expect(window.location.hash).toBe('#/users/5');
      expect(handler).toHaveBeenCalledWith({ params: { id: '5' }, query: {} });
    });

    it('preserves default behavior for ctrl/meta clicks', () => {
      const { handler, anchor } = setup();

      expect(click(anchor, { ctrlKey: true })).toBe(false);
      expect(click(anchor, { metaKey: true })).toBe(false);

      expect(window.location.hash).toBe('');
      expect(handler).not.toHaveBeenCalled();
    });

    it('ignores clicks on anchors without a #/ href', () => {
      document.body.innerHTML = '<a href="https://example.com" id="ext">ext</a>';
      const router = createRouter({});
      const uninstall = router.installLinkInterceptor(document);
      cleanupFns.push(uninstall);
      const anchor = document.getElementById('ext');

      expect(click(anchor)).toBe(false);
      expect(window.location.hash).toBe('');
    });
  });
});
